import { View, Text, Switch, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [on, setOn] = useState(false);
  return (
    <View style={styles.row}>
      <Text style={styles.label}>Мэдэгдэл авах</Text>
      <Switch nativeID="notif" value={on} />
      {/* энд бичнэ үү: onValueChange холбож, төлөвийг харуул */}
      <Text nativeID="status" style={styles.status}>Унтраалттай</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flex: 1, padding: 24, gap: 12, alignItems: "center", justifyContent: "center" },
  label: { fontSize: 18, fontWeight: "600" },
  status: { fontSize: 16, color: "#64748b" },
});

registerRootComponent(App);

import { View, Text, Switch, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [on, setOn] = useState(false);
  return (
    <View style={styles.row}>
      <Text style={styles.label}>Мэдэгдэл авах</Text>
      <Switch nativeID="notif" value={on} onValueChange={setOn} />
      <Text nativeID="status" style={styles.status}>{on ? "Асаалттай" : "Унтраалттай"}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flex: 1, padding: 24, gap: 12, alignItems: "center", justifyContent: "center" },
  label: { fontSize: 18, fontWeight: "600" },
  status: { fontSize: 16, color: "#64748b" },
});

registerRootComponent(App);
